import{_ as i,o as t,c as a,ag as o}from"./chunks/framework.DC2M1AAK.js";const u=JSON.parse('{"title":"Security policy","description":"","frontmatter":{},"headers":[],"relativePath":"community/security-policy.md","filePath":"community/security-policy.md"}'),r={name:"community/security-policy.md"};function s(n,e,c,l,d,p){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="security-policy" tabindex="-1">Security policy <a class="header-anchor" href="#security-policy" aria-label="Permalink to &quot;Security policy&quot;">​</a></h1><h2 id="reporting-a-vulnerability" tabindex="-1">Reporting a vulnerability <a class="header-anchor" href="#reporting-a-vulnerability" aria-label="Permalink to &quot;Reporting a vulnerability&quot;">​</a></h2><p>Please report security problems privately to the maintainers (open a GitHub security advisory on this repository, or email the address in the repository profile). Do not open a public issue. We aim to acknowledge within 3 working days and to ship a fix or a mitigation before any public disclosure.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>The gateway, the core runtime, the Verdict package, the widget, the example domain, and the deploy files in this repository. Your own domains, backends and model providers are yours.</p><h2 id="what-we-consider-in-scope" tabindex="-1">What we consider in scope <a class="header-anchor" href="#what-we-consider-in-scope" aria-label="Permalink to &quot;What we consider in scope&quot;">​</a></h2><ul><li>Reading or acting on another user&#39;s session (owner checks, identity verification).</li><li>Any path by which a model-emitted value reaches a client as HTML or an unlisted URL scheme.</li><li>Any write that bypasses the confirm gate.</li><li>Secrets or private user text reaching logs, spans or ledgers.</li><li>Denial of service through the rate-limit or cap paths.</li></ul><p>See <code>docs/SECURITY.md</code> for the design and <code>docs/PRODUCTION-CHECKLIST.md</code> for the deploy gate.</p><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/SECURITY.md">SECURITY.md</a> — edit it there; the site mirrors the repository.</small></p>',10)])])}const m=i(r,[["render",s]]);export{u as __pageData,m as default};
